#!/bin/bash\n\necho \"🐳 Building NetOps Assistant Docker image...\"\necho \"=============================================\"\necho \"\"\n\ndocker build -t netops-assistant:latest .\n\nif [ $? -eq 0 ]; then\n    echo \"\"\n    echo \"✅ Build successful!\"\n    echo \"\"\n    echo \"Run the container with:\"\n    echo \"  docker run -p 5000:5000 -p 8000:8000 --cap-add=NET_ADMIN netops-assistant:latest\"\n    echo \"\"\n    echo \"Or use Docker Compose:\"\n    echo \"  docker-compose up\"\nelse\n    echo \"❌ Build failed!\"\n    exit 1\nfi\n